WIDTHS = (12, 24, 40, 48)
SHIFTS = (6, 7, 9, 8)
RECIPES = (
    (5601, False, 56, (32, 32), 0.0),
    (5602, True, 56, (32, 32), 0.0),
    (5603, True, 56, (32, 32), 0.0),
    (5611, False, 110, (16, 16), 0.25),
    (5612, True, 110, (16, 16), 0.12),
    (5613, False, 100, (24, 24), 0.10),
    (5621, True, 180, (48, 16), 0.0),
)


def inputs(records):
    return np.stack([channels(input_pixels(r["file"], "card")) for r in records])


def tensor(images):
    return torch.from_numpy(images).permute(0, 3, 1, 2).float()


def load_data():
    rows = frozen_rows()
    originals = [r for r in rows if r["split"] == "train"]
    val = [r for r in rows if r["split"] == "val"]
    images = inputs(originals)
    labels = [r["class_id"] - 1 for r in originals]
    groups = Counter((r["class_id"], r["source_group"]) for r in originals)
    weights = np.array(
        [1 / groups[r["class_id"], r["source_group"]] for r in originals]
    )
    for i in range(15):
        mask = np.array(labels) == i
        weights[mask] /= weights[mask].sum() ** 0.8

    with ZipFile(TRAIN_ARCHIVE) as archive:
        members = training_members(archive, rows)
        variants = np.empty((len(members), 56, 56, 3), dtype=np.uint8)
        for i, member in enumerate(members):
            with Image.open(BytesIO(read_variant(archive, member))) as image:
                rgb = np.asarray(image.convert("RGB")).astype(np.uint16)
            r, g, b = (rgb >> [3, 2, 3]).transpose(2, 0, 1)
            variants[i] = channels(((r << 11) | (g << 5) | b).astype(np.uint16))
            labels.append(member["class_id"] - 1)
    return (
        np.concatenate([images, variants]),
        np.array(labels),
        weights / weights.sum(),
        tensor(inputs(val)),
        torch.tensor([r["class_id"] - 1 for r in val]),
    )


class RoleNet(nn.Module):
    def __init__(self, cosine):
        super().__init__()
        self.cosine = cosine
        self.convs = nn.ModuleList()
        self.norms = nn.ModuleList()
        cin = 3
        for cout in WIDTHS:
            self.convs.append(nn.Conv2d(cin, cout, 3, bias=False))
            self.norms.append(nn.BatchNorm2d(cout))
            cin = cout
        self.head = nn.Linear(WIDTHS[-1] * 9, 15, bias=not cosine)

    def features(self, x):
        for i, (conv, norm) in enumerate(zip(self.convs, self.norms)):
            x = norm(conv(x)).relu()
            if i < 3:
                x = F.max_pool2d(x, 2)
        return x.flatten(1)

    def forward(self, x):
        x = F.dropout(self.features(x / 127), 0.15, self.training)
        if self.cosine:
            return 18 * F.linear(F.normalize(x), F.normalize(self.head.weight))
        return self.head(x)


def augment(x):
    n = len(x)
    angle = torch.empty(n).uniform_(-0.17, 0.17)
    sx, sy = torch.empty(2, n).uniform_(0.84, 1.17)
    sx *= torch.where(torch.rand(n) < 0.5, -1, 1)
    mat = torch.stack(
        (
            angle.cos() * sx,
            -angle.sin() * sy,
            torch.empty(n).uniform_(-0.12, 0.12),
            angle.sin() * sx,
            angle.cos() * sy,
            torch.empty(n).uniform_(-0.12, 0.12),
        ),
        1,
    )
    grid = F.affine_grid(mat.reshape(n, 2, 3), x.shape, align_corners=False)
    x = F.grid_sample(x, grid, padding_mode="border", align_corners=False)
    gain = torch.empty(n, 3, 1, 1).uniform_(0.9, 1.1)
    return (
        (x * gain + torch.empty(n, 1, 1, 1).uniform_(-9, 9))
        .clamp(0, 127)
        .round()
        .contiguous(memory_format=torch.channels_last)
    )


@torch.no_grad()
def quantize(net, calibration):
    x = calibration / 127
    scales = torch.full((3,), 127.0)
    model = {"shifts": np.array(SHIFTS)}
    for i, (conv, norm, shift) in enumerate(zip(net.convs, net.norms, SHIFTS)):
        x = norm(conv(x)).relu()
        peak = torch.quantile(
            x[:, :, ::2, ::2].transpose(0, 1).flatten(1), 0.998, dim=1
        )
        gain = norm.weight * torch.rsqrt(norm.running_var + norm.eps)
        base = (
            conv.weight
            * gain[:, None, None, None]
            * (2**shift)
            / scales[None, :, None, None]
        )
        scales = torch.minimum(
            124 / peak.clamp_min(0.1),
            126 / base.abs().flatten(1).amax(1).clamp_min(1e-8),
        )
        model[f"w{i}"] = (
            (base * scales[:, None, None, None]).round().to(torch.int8).numpy()
        )
        bias = (norm.bias - gain * norm.running_mean) * scales * (2**shift)
        model[f"b{i}"] = (bias + 2 ** (shift - 1)).round().int().numpy()
        if i < 3:
            x = F.max_pool2d(x, 2)
    weights = F.normalize(net.head.weight) if net.cosine else net.head.weight
    weights = weights / scales.repeat_interleave(9)
    unit = 126 / weights.abs().max()
    model["wf"] = (weights * unit).round().to(torch.int8).numpy()
    model["bf"] = (
        np.zeros(15, np.int32)
        if net.cosine
        else (net.head.bias * unit).round().int().numpy()
    )
    return model


@torch.no_grad()
def quant_features(x, model):
    for i, shift in enumerate(SHIFTS):
        weights = torch.from_numpy(model[f"w{i}"]).float()
        bias = torch.from_numpy(model[f"b{i}"]).float()
        x = (F.conv2d(x, weights, bias) / (2**shift)).floor().clamp(0, 127)
        if i < 3:
            x = F.max_pool2d(x, 2)
    return x.flatten(1)


@torch.no_grad()
def quant_scores(x, model):
    return F.linear(
        quant_features(x, model),
        torch.from_numpy(model["wf"]).float(),
        torch.from_numpy(model["bf"]).float(),
    )


def accuracy(pred, labels):
    match = pred == labels
    macro = torch.stack([match[labels == i].float().mean() for i in labels.unique()])
    return int(match.sum()), float(macro.mean())


@torch.no_grad()
def refit_head(model, images, labels, weights, vx, vy):
    features = torch.cat(
        [
            quant_features(tensor(images[i : i + 96]), model)
            for i in range(0, len(images), 96)
        ]
    ).double()
    target = F.one_hot(torch.from_numpy(labels), 15).double()
    weights = torch.from_numpy(
        np.concatenate(
            [
                0.65 * weights,
                np.full(
                    len(labels) - len(weights), 0.35 / (len(labels) - len(weights))
                ),
            ]
        )
    ).unsqueeze(1)
    mean = (weights * features).sum(0)
    counts = (weights * target).sum(0)
    x = features - mean
    y = target - counts
    old = torch.from_numpy(model["wf"].T).double()
    prior = x @ old
    old = old * (weights * y * prior).sum() / (weights * prior.square()).sum()
    cov = x.T @ (weights * x)
    rhs = x.T @ (weights * (y - x @ old))
    var = cov.diagonal().mean() * torch.eye(len(mean), dtype=torch.float64)
    val = quant_features(vx, model)
    best = accuracy(quant_scores(vx, model).argmax(1), vy)
    result = model
    selected = None
    trials = []
    for strength in (0.1, 1.0, 10.0):
        head = old + torch.linalg.solve(cov + strength * var, rhs)
        bias = counts - mean @ head
        scale = 126 / head.abs().max()
        wf = (head.T * scale).round().to(torch.int8)
        bf = (bias * scale).round().int()
        key = accuracy(F.linear(val, wf.float(), bf.float()).argmax(1), vy)
        trials.append(dict(strength=strength, correct=key[0], macro=key[1]))
        if key > best:
            best = key
            result = dict(model, wf=wf.numpy(), bf=bf.numpy())
            selected = trials[-1]
    return result, selected, trials


def train(out, recipes=RECIPES):
    if out.resolve() == MODEL56.resolve():
        raise ValueError("Choose a separate directory for the candidate weights")
    out.mkdir(parents=True, exist_ok=True)
    torch.set_num_threads(5)
    images, labels, weights, vx, vy = load_data()
    n = len(weights)
    calibration = tensor(
        images[np.random.default_rng(56).choice(len(images), 96, replace=False)]
    )
    history = []
    best = None
    for seed, cosine, epochs, (early, late), mixup in recipes:
        rng = np.random.default_rng(seed)
        torch.manual_seed(seed)
        net = RoleNet(cosine).to(memory_format=torch.channels_last)
        opt = torch.optim.AdamW(net.parameters(), lr=0.0016, weight_decay=0.012)
        scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(
            opt, epochs, eta_min=0.00007
        )
        order = rng.permutation(np.arange(n, len(images)))
        cursor = 0
        for epoch in range(1, epochs + 1):
            net.train()
            take = early if epoch <= epochs // 2 else late
            for _ in range(16):
                if cursor == len(order):
                    rng.shuffle(order)
                    cursor = 0
                variants = order[cursor : cursor + take]
                cursor += len(variants)
                real = rng.choice(n, 64 - len(variants), p=weights)
                ids = np.concatenate((real, variants))
                batch = augment(tensor(images[ids]))
                target = torch.from_numpy(labels[ids])
                fraction = 1.0
                if mixup and rng.random() < 0.5:
                    fraction = rng.beta(mixup, mixup)
                    batch = fraction * batch + (1 - fraction) * batch.flip([0])
                logits = net(batch)
                loss = F.cross_entropy(logits, target, label_smoothing=0.035)
                if fraction != 1.0:
                    loss = fraction * loss + (1 - fraction) * F.cross_entropy(
                        logits, target.flip([0]), label_smoothing=0.035
                    )
                opt.zero_grad(set_to_none=True)
                loss.backward()
                opt.step()
            scheduler.step()
            if epoch % 2 and epoch != epochs:
                continue
            net.eval()
            model = quantize(net, calibration)
            hit, macro = accuracy(quant_scores(vx, model).argmax(1), vy)
            history.append(
                dict(seed=seed, cosine=cosine, epoch=epoch, correct=hit, macro=macro)
            )
            if best is None or (hit, macro) > best:
                best = (hit, macro)
                best_model = model
                chosen = history[-1]
                print(
                    f"best seed={seed} epoch={epoch} val={hit}/{len(vy)} macro={macro:.3f}",
                    flush=True,
                )
            if epoch % 10 == 0:
                print(f"seed={seed} epoch={epoch} val={hit}/{len(vy)}", flush=True)
    model, head, trials = refit_head(best_model, images, labels, weights, vx, vy)
    metadata = dict(
        recipes=recipes,
        selected=chosen,
        validation=history,
        head_trials=trials,
        training_originals=n,
        training_variants=len(images) - n,
        archive_sha256=hashlib.sha256(TRAIN_ARCHIVE.read_bytes()).hexdigest(),
        torch_version=torch.__version__,
    )
    if head is not None:
        metadata["selected"] = dict(chosen, **head)
    np.savez_compressed(out / "integer_model.npz", **model)
    for name in ("classes.json", "splits.json"):
        shutil.copyfile(MODEL56 / name, out / name)
    (out / "training.json").write_text(json.dumps(metadata, indent=2) + "\n", "utf8")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--out", type=Path, default=ROOT / "build" / "role56")
    parser.add_argument("--seeds", type=int, nargs="+", choices=[r[0] for r in RECIPES])
    args = parser.parse_args()
    train(args.out, [r for r in RECIPES if args.seeds is None or r[0] in args.seeds])
